template <typename Key, int T>
struct BTreeNode {
    // entre T-1 y 2T-1 claves, ordenadas
    std::vector<Key> keys;
    // k claves y no es hoja -> k+1 hijos
    std::vector<std::unique_ptr<BTreeNode>> children;
    bool isLeaf = true;
    bool isFull() const {
        return keys.size() == 2 * T - 1;
    }
};

template <typename Key, int T>
const BTreeNode<Key, T>* search(
        const BTreeNode<Key, T>* node, const Key& k) {
    if (node == nullptr) return nullptr;
    std::size_t i = 0;
    while (i < node->keys.size() && k > node->keys[i]) ++i;
    if (i < node->keys.size() && k == node->keys[i])
        return node;                       // encontrada
    if (node->isLeaf) return nullptr;      // no existe
    return search(node->children[i].get(), k);  // 1 lectura
}
